files.content:
@layer syn.tokens, syn.base, syn.components, syn.semantic, syn.recipes, syn.geometry, syn.symbols, syn.effects, syn.viz, syn.utilities;

@layer syn.tokens {
  :where(.syn-root) {
    color-scheme: light;
    --syn-font: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    --syn-mono: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
    --syn-type-xs: .75rem;
    --syn-type-sm: .875rem;
    --syn-type-base: 1rem;
    /* Type roles are independent from theme palettes and optional font loading. */
    --syn-type-body: var(--syn-type-base);
    --syn-type-heading: clamp(1.15rem, 2.4vw, 1.55rem);
    --syn-type-section: clamp(1.5rem, 1.25rem + 1.25vw, 2.125rem);
    --syn-type-display: clamp(2rem, 5.5vw, 4rem);
    --syn-leading-body: 1.55;
    --syn-tracking-display: -.045em;
    --syn-space-1: .375rem;
    --syn-space-2: .75rem;
    --syn-space-3: 1.125rem;
    --syn-space-4: 1.75rem;
    --syn-space-5: 2.5rem;
    /* Opt-in fluid rhythm, with fixed fallbacks for engines without vi units.
       Existing --syn-space-* tokens and component defaults are unchanged. */
    --syn-space-fluid-1: var(--syn-space-1);
    --syn-space-fluid-2: var(--syn-space-2);
    --syn-space-fluid-3: var(--syn-space-3);
    --syn-space-fluid-4: var(--syn-space-4);
    --syn-cut: .9rem;
    --syn-radius: .25rem;
    --syn-line: 1.55;
    --syn-control-height: 2.75rem;
    --syn-control-padding-block: .7rem;
    --syn-row-padding-block: .7rem;
    --syn-card-padding: var(--syn-space-3);
    --syn-shadow-sm: 0 1px 3px rgb(0 0 0 / 8%);
    --syn-shadow-raised: 0 8px 24px rgb(0 0 0 / 12%);
    --syn-shadow-overlay: 0 20px 70px rgb(0 0 0 / 45%);
    --syn-ease: cubic-bezier(.2, .8, .2, 1);
    --syn-ease-enter: cubic-bezier(.16, 1, .3, 1);
    --syn-duration-fast: 150ms;
    --syn-duration-standard: 240ms;
  }
  /* vi is the logical viewport inline axis; no JavaScript or media queries.
     Feature-gating also preserves fixed spacing in older CSS engines. */
  @supports (width: 1vi) {
    :where(.syn-root) {
      --syn-space-fluid-1: clamp(var(--syn-space-1), calc(.25rem + .65vi), var(--syn-space-2));
      --syn-space-fluid-2: clamp(var(--syn-space-2), calc(.5rem + 1vi), var(--syn-space-3));
      --syn-space-fluid-3: clamp(var(--syn-space-3), calc(.75rem + 1.5vi), var(--syn-space-4));
      --syn-space-fluid-4: clamp(var(--syn-space-4), calc(1rem + 2vi), var(--syn-space-5));
    }
  }
  /* Derived surfaces recompute inside nested themes, not just on the parent. */
  :where(.syn-root, .syn-root [data-syn-theme]) {
    --syn-surface-recessed: color-mix(in srgb, var(--syn-bg) 88%, var(--syn-surface));
    --syn-surface-raised: color-mix(in srgb, var(--syn-surface) 72%, var(--syn-surface-hi));
    /* Nested-theme-aware overlay roles; no hardcoded light/dark surface colors. */
    --syn-surface-floating: color-mix(in srgb, var(--syn-surface) 45%, var(--syn-surface-hi));
    --syn-border-floating: var(--syn-frame-strong);
    --syn-border-subtle: color-mix(in srgb, var(--syn-frame) 60%, transparent);
    /* These aliases recompute in nested themed regions. */
    --syn-text-subtle: var(--syn-muted);
    --syn-border-default: var(--syn-frame);
    --syn-border-hover: var(--syn-frame-strong);
    --syn-border-focus: var(--syn-accent);
    --syn-focus-ring: var(--syn-accent);
    --syn-surface-interactive: var(--syn-surface-hi);
    --syn-surface-hover: color-mix(in srgb, var(--syn-surface-hi) 83%, var(--syn-accent));
    --syn-surface-pressed: var(--syn-accent-soft);
    /* Keep hover contrast identical to the approved accent/foreground pair by default. */
    --syn-primary-hover-bg: var(--syn-accent);
    --syn-font-ui: var(--syn-font);
    --syn-font-display: var(--syn-font);
  }
  /* Compact presentation is an opt-in layout control, never a font-size override. */
  :where(.syn-root[data-syn-density="compact"], .syn-root [data-syn-density="compact"]) {
    --syn-control-height: 2.25rem;
    --syn-control-padding-block: .3rem;
    --syn-row-padding-block: .4rem;
    --syn-card-padding: var(--syn-space-2);
  }
  /* Explicit default restores regular spacing inside a compact ancestor. */
  :where(.syn-root[data-syn-density="comfortable"], .syn-root [data-syn-density="comfortable"]) {
    --syn-control-height: 2.75rem;
    --syn-control-padding-block: .7rem;
    --syn-row-padding-block: .7rem;
    --syn-card-padding: var(--syn-space-3);
  }
  /* Spacious is for form-heavy or review contexts, without scaling typography. */
  :where(.syn-root[data-syn-density="spacious"], .syn-root [data-syn-density="spacious"]) {
    --syn-control-height: 3.25rem;
    --syn-control-padding-block: .95rem;
    --syn-row-padding-block: 1rem;
    --syn-card-padding: var(--syn-space-4);
  }
  /* Visual richness is independent of palette, geometry and density.
     Explicit values on descendants reset the inherited presentation profile. */
  :where(.syn-root, .syn-root [data-syn-intensity="standard"]) {
    --syn-grid-alpha: 5%;
    --syn-glow-alpha: 12%;
    --syn-wash-alpha: 15%;
    --syn-wash-secondary-alpha: 10%;
    --syn-horizon-alpha: 10%;
    --syn-scanline-alpha: 10%;
  }
  :where(.syn-root[data-syn-intensity="quiet"], .syn-root [data-syn-intensity="quiet"]) {
    --syn-grid-alpha: 1%;
    --syn-glow-alpha: 0%;
    --syn-wash-alpha: 4%;
    --syn-wash-secondary-alpha: 3%;
    --syn-horizon-alpha: 2%;
    --syn-scanline-alpha: 0%;
  }
  :where(.syn-root[data-syn-intensity="cinematic"], .syn-root [data-syn-intensity="cinematic"]) {
    --syn-grid-alpha: 10%;
    --syn-glow-alpha: 25%;
    --syn-wash-alpha: 26%;
    --syn-wash-secondary-alpha: 18%;
    --syn-horizon-alpha: 17%;
    --syn-scanline-alpha: 12%;
  }
  /* Neutral default; named palettes override it independently. */
  :where(.syn-root, .syn-root[data-syn-theme="studio"], .syn-root [data-syn-theme="studio"]) {
    color-scheme: light;
    --syn-bg: #f5f7fb;
    --syn-surface: #ffffff;
    --syn-surface-hi: #eaf0f8;
    --syn-text: #15233a;
    --syn-muted: #4b5d76;
    --syn-accent: #2458c6;
    --syn-accent-2: #176b80;
    --syn-on-accent: #ffffff;
    --syn-frame: #b8c6d8;
    --syn-frame-strong: #6685b2;
    --syn-danger: #ad2637;
    --syn-success: #17694b;
    --syn-warning: #92500a;
    --syn-accent-soft: color-mix(in srgb, var(--syn-accent) 9%, transparent);
    --syn-radius: .25rem;
    --syn-cut: .9rem;
  }
  :where(.syn-root[data-syn-theme="grid"], .syn-root [data-syn-theme="grid"]) {
    color-scheme: dark;
    --syn-bg: #080f19;
    --syn-surface: #111f2c;
    --syn-surface-hi: #172a3b;
    --syn-text: #edf9ff;
    --syn-muted: #adbfca;
    --syn-accent: #76e7f7;
    --syn-accent-2: #f7b06c;
    --syn-on-accent: #07121a;
    --syn-frame: #345569;
    --syn-frame-strong: #5086a0;
    --syn-danger: #ffaaa4;
    --syn-success: #8ce6bb;
    --syn-warning: #ffd08b;
    --syn-accent-soft: color-mix(in srgb, var(--syn-accent) 11%, transparent);
    --syn-radius: .25rem;
    --syn-cut: .9rem;
  }
  :where(.syn-root[data-syn-theme="noir"], .syn-root [data-syn-theme="noir"]) {
    color-scheme: dark;
    --syn-bg: #0e0e12;
    --syn-surface: #1c1b20;
    --syn-surface-hi: #2a2628;
    --syn-text: #f8eee5;
    --syn-muted: #c3b5aa;
    --syn-accent: #f1b574;
    --syn-accent-2: #9acfd5;
    --syn-on-accent: #1c100b;
    --syn-frame: #625048;
    --syn-frame-strong: #9a7557;
    --syn-danger: #ffc1ac;
    --syn-success: #a5e4bc;
    --syn-warning: #fbd18c;
    --syn-accent-soft: color-mix(in srgb, var(--syn-accent) 10%, transparent);
    --syn-radius: .25rem;
    --syn-cut: .9rem;
  }
  :where(.syn-root[data-syn-theme="industrial"], .syn-root [data-syn-theme="industrial"]) {
    color-scheme: dark;
    --syn-bg: #121417;
    --syn-surface: #1c2023;
    --syn-surface-hi: #2a3033;
    --syn-text: #f3f2ee;
    --syn-muted: #c0c5c8;
    --syn-accent: #ffb36b;
    --syn-accent-2: #d6c9a9;
    --syn-on-accent: #241409;
    --syn-frame: #69747b;
    --syn-frame-strong: #a0b0b7;
    --syn-danger: #ffb2a7;
    --syn-success: #8dedb0;
    --syn-warning: #ffd08f;
    --syn-accent-soft: color-mix(in srgb, var(--syn-accent) 11%, transparent);
    --syn-radius: .15rem;
    --syn-cut: .45rem;
  }
  :where(.syn-root[data-syn-theme="terminal"], .syn-root [data-syn-theme="terminal"]) {
    color-scheme: dark;
    --syn-bg: #07130d;
    --syn-surface: #0d1f17;
    --syn-surface-hi: #153325;
    --syn-text: #d9fce7;
    --syn-muted: #a2d2b5;
    --syn-accent: #65e8a0;
    --syn-accent-2: #a6f0ce;
    --syn-on-accent: #062011;
    --syn-frame: #3e8761;
    --syn-frame-strong: #69bd8a;
    --syn-danger: #f6a8a8;
    --syn-success: #74e7a7;
    --syn-warning: #eccd86;
    --syn-accent-soft: color-mix(in srgb, var(--syn-accent) 11%, transparent);
    --syn-radius: 0;
    --syn-cut: 0;
  }
  :where(.syn-root[data-syn-theme="corporate"], .syn-root [data-syn-theme="corporate"]) {
    color-scheme: light;
    --syn-bg: #f5f8fc;
    --syn-surface: #ffffff;
    --syn-surface-hi: #e8eef6;
    --syn-text: #18273c;
    --syn-muted: #4b5d72;
    --syn-accent: #155ac8;
    --syn-accent-2: #087a8a;
    --syn-on-accent: #ffffff;
    --syn-frame: #73859b;
    --syn-frame-strong: #526c8c;
    --syn-danger: #b42331;
    --syn-success: #147446;
    --syn-warning: #9a5600;
    --syn-accent-soft: color-mix(in srgb, var(--syn-accent) 9%, transparent);
    --syn-radius: .5rem;
    --syn-cut: 0;
  }
  :where(.syn-root[data-syn-theme="minimal"], .syn-root [data-syn-theme="minimal"]) {
    color-scheme: light;
    --syn-bg: #f7f7f5;
    --syn-surface: #ffffff;
    --syn-surface-hi: #ebedee;
    --syn-text: #202328;
    --syn-muted: #5c6168;
    --syn-accent: #313a45;
    --syn-accent-2: #56606b;
    --syn-on-accent: #ffffff;
    --syn-frame: #7b8189;
    --syn-frame-strong: #555b62;
    --syn-danger: #aa2f3c;
    --syn-success: #1f6c45;
    --syn-warning: #8d5200;
    --syn-accent-soft: color-mix(in srgb, var(--syn-accent) 7%, transparent);
    --syn-radius: .375rem;
    --syn-cut: 0;
  }


  /* Opt-in system palette: Studio in light mode, Grid in dark mode.
     Engines without light-dark() fall back to the neutral Studio palette. */
  @supports (color: light-dark(white, black)) {
    :where(.syn-root[data-syn-theme="auto"], .syn-root [data-syn-theme="auto"]) {
      color-scheme: light dark;
      --syn-bg: light-dark(#f5f7fb, #080f19);
      --syn-surface: light-dark(#ffffff, #111f2c);
      --syn-surface-hi: light-dark(#eaf0f8, #172a3b);
      --syn-text: light-dark(#15233a, #edf9ff);
      --syn-muted: light-dark(#4b5d76, #adbfca);
      --syn-accent: light-dark(#2458c6, #76e7f7);
      --syn-accent-2: light-dark(#176b80, #f7b06c);
      --syn-on-accent: light-dark(#ffffff, #07121a);
      --syn-frame: light-dark(#b8c6d8, #345569);
      --syn-frame-strong: light-dark(#6685b2, #5086a0);
      --syn-danger: light-dark(#ad2637, #ffaaa4);
      --syn-success: light-dark(#17694b, #8ce6bb);
      --syn-warning: light-dark(#92500a, #ffd08b);
      --syn-accent-soft: light-dark(color-mix(in srgb, var(--syn-accent) 9%, transparent), color-mix(in srgb, var(--syn-accent) 11%, transparent));
      --syn-radius: .25rem;
      --syn-cut: .9rem;
    }
  }
  /* Experimental perceptual mixing: explicitly enable per root or themed region.
     The default sRGB role remains intact on unsupported engines and elsewhere.
     Do not recolor semantic text/accent pairings without a contrast audit. */
  @supports (color: color-mix(in oklch, red, blue)) {
    :where(.syn-root[data-syn-color-space="oklch"],
           .syn-root [data-syn-color-space="oklch"]) {
      --syn-surface-hover: color-mix(in oklch, var(--syn-surface-hi) 83%, var(--syn-accent));
    }
  }

  /* Technical typography is an explicit choice, not the neutral root default. */
  :where(.syn-root[data-syn-theme="grid"],
         .syn-root [data-syn-theme="grid"], .syn-root[data-syn-theme="terminal"],
         .syn-root [data-syn-theme="terminal"]) {
    --syn-font-ui: var(--syn-mono);
    --syn-font-display: var(--syn-mono);
  }

  /* Higher contrast preserves nested theme and intensity overrides.
     Custom application CSS can still override these layered defaults. */
  @media (prefers-contrast: more) {
    :where(.syn-root, .syn-root [data-syn-theme], .syn-root [data-syn-intensity]) {
      --syn-border-subtle: var(--syn-frame-strong);
      --syn-border-default: var(--syn-frame-strong);
      --syn-shadow-raised: 0 0 0 transparent;
      --syn-grid-alpha: 0%;
      --syn-glow-alpha: 0%;
      --syn-wash-alpha: 0%;
      --syn-wash-secondary-alpha: 0%;
      --syn-horizon-alpha: 0%;
      --syn-scanline-alpha: 0%;
    }
  }
}
@layer syn.base {
  :where(.syn-root), :where(.syn-root) *, :where(.syn-root) *::before, :where(.syn-root) *::after { box-sizing: border-box; }
  .syn-root {
    margin: 0;
    font: 400 var(--syn-type-body)/var(--syn-leading-body) var(--syn-font);
    color: var(--syn-text);
    background: var(--syn-bg);
  }
  /* Keep native [hidden] authoritative over author-level component display rules.
     hidden=until-found must retain the browser's find-in-page reveal behavior. */
  :where(.syn-root[hidden]:not([hidden="until-found" i]),
         .syn-root [hidden]:not([hidden="until-found" i])) {
    display: none !important;
  }
  .syn-root :where([data-syn-theme]) { color: var(--syn-text); background-color: var(--syn-bg); }
  .syn-root.syn-page { min-height: 100svh; }
  .syn-root :where(h1,h2,h3,h4,p) { margin-block-start: 0; }
  .syn-root :where(h1,h2,h3,h4) { line-height: 1.12; letter-spacing: -.025em; overflow-wrap: anywhere; }
  .syn-root :where(button,input,select,textarea) { font: inherit; }
  .syn-root :where(a) { color: var(--syn-accent); text-underline-offset: .2em; }
  .syn-root :where(:focus-visible) { outline: 3px solid var(--syn-focus-ring); outline-offset: 3px; }
  .syn-root :where(:disabled, [aria-disabled="true"]) { cursor: not-allowed; opacity: .55; }
  .syn-root :where(::selection) { color: var(--syn-on-accent); background: var(--syn-accent); }
  @media (prefers-reduced-motion: reduce) {
    .syn-root *, .syn-root *::before, .syn-root *::after {
      scroll-behavior: auto !important;
      transition-duration: 0s !important;
      animation-duration: 0s !important;
    }
  }
  @media (forced-colors: active) {
    .syn-root :where(:focus-visible) { outline-color: Highlight; }
  }
}
@layer syn.components {
  /* All component rules match the root itself or a descendant, never a host sibling. */
  :where(.syn-root, .syn-root *) {
    &.syn-shell { width: min(100% - var(--syn-shell-inline-inset, 2rem), var(--syn-shell-max, 72rem)); margin-inline: auto; }
    &.syn-header { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--syn-header-gap, 1rem); padding-block: var(--syn-header-padding-block, 2rem); }
    &.syn-nav { display: flex; align-items: center; flex-wrap: wrap; gap: var(--syn-nav-gap, 1rem); }
    &.syn-nav a { color: var(--syn-muted); text-decoration: none; font: 600 var(--syn-type-sm) var(--syn-font-ui); }
    &.syn-nav a:hover, &.syn-nav a[aria-current] { color: var(--syn-accent); }
    &.syn-stage {
      --syn-stage-pad: clamp(1.25rem, 4vw, 3rem);
      background: var(--syn-bg);
      color: var(--syn-text);
      border: 1px solid var(--syn-frame);
      padding: var(--syn-stage-pad);
      margin-block: 1.5rem;
      position: relative;
      isolation: isolate;
    }
    &.syn-stage-header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 1rem; margin-block-end: 1.75rem; }
    /* Component-local variables customize intrinsic layouts without a utility compiler. */
    &.syn-grid { display: grid; gap: var(--syn-grid-gap, 1rem); grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--syn-grid-min, 17rem)), 1fr)); }
    &.syn-layout { display: grid; gap: var(--syn-layout-gap, 1.25rem); grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--syn-layout-min, 21rem)), 1fr)); align-items: start; }
    &.syn-stack { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--syn-stack-gap, var(--syn-space-3)); }
    /* A wrapping cluster for filters, actions, chips and navigation.
       Consumers can customize alignment without an extra utility API. */
    &.syn-inline {
      display: flex; flex-wrap: wrap; min-inline-size: 0;
      align-items: var(--syn-inline-align, center);
      justify-content: var(--syn-inline-justify, flex-start);
      gap: var(--syn-inline-gap, var(--syn-space-2));
    }
    /* Intrinsic main + optional aside; direct children only, main first.
       The narrow layout naturally wraps even in an embedded container. */
    &.syn-sidecar {
      display: flex; flex-wrap: wrap; min-inline-size: 0;
      align-items: var(--syn-sidecar-align, start);
      gap: var(--syn-sidecar-gap, var(--syn-space-3));
    }
    &.syn-sidecar > :first-child {
      flex: 999 1 0;
      min-inline-size: min(100%, var(--syn-sidecar-main-min, 28rem));
      overflow-wrap: anywhere;
    }
    &.syn-sidecar > :last-child:not(:first-child) {
      flex: 1 1 var(--syn-sidecar-aside-width, 16rem);
      min-inline-size: min(100%, var(--syn-sidecar-aside-width, 16rem));
      overflow-wrap: anywhere;
    }
    &.syn-panel {
      position: relative; padding: var(--syn-panel-padding, clamp(1rem, 2.8vw, 1.75rem)); overflow-wrap: anywhere;
      color: var(--syn-panel-color, var(--syn-text)); border: var(--syn-panel-border-width, 1px) solid var(--syn-panel-border-color, var(--syn-border-subtle));
      border-radius: var(--syn-panel-radius, 0);
      background: var(--syn-panel-bg, var(--syn-surface));
      min-width: 0;
    }
    /* Native inert blocks interaction; this is only a visible presentation cue. */
    &.syn-panel:where([inert]) { border-style: dashed; background: var(--syn-surface-recessed); }
    &.syn-panel--raised { box-shadow: var(--syn-shadow-raised); }
    &.syn-panel--cut::after {
      content: ""; pointer-events: none; position: absolute;
      inset-inline-end: -1px; inset-block-end: -1px;
      inline-size: var(--syn-cut); block-size: var(--syn-cut);
      background: var(--syn-panel-cut-fill, var(--syn-bg));
      clip-path: polygon(100% 0, 0 100%, 100% 100%);
    }
    &.syn-panel--cut:dir(rtl)::after {
      clip-path: polygon(0 0, 0 100%, 100% 100%);
    }
    @media (forced-colors: active) { &.syn-stage, &.syn-panel { border-color: CanvasText; } }
  }
}
@layer syn.components {
  /* All component rules match the root itself or a descendant, never a host sibling. */
  :where(.syn-root, .syn-root *) {
    &.syn-logo { display: inline-block; max-inline-size: 100%; overflow-wrap: anywhere; font: 700 .95rem/1 var(--syn-mono); letter-spacing: .22em; text-decoration: none; color: var(--syn-text); }
    &.syn-eyebrow { font: 700 var(--syn-type-xs)/1.4 var(--syn-font-ui); letter-spacing: .15em; text-transform: uppercase; color: var(--syn-accent); }
    &.syn-title, &.syn-display { font-family: var(--syn-font-display); font-size: var(--syn-type-display); line-height: 1.08; letter-spacing: var(--syn-tracking-display); margin-block: 1rem; max-width: 14ch; text-wrap: balance; }
    &.syn-heading { font-family: var(--syn-font-display); font-size: var(--syn-type-heading); line-height: 1.2; margin-block: .5rem 1rem; }
    &.syn-section-heading { overflow-wrap: anywhere; font: 650 var(--syn-type-section)/1.16 var(--syn-font-display); letter-spacing: -.03em; margin-block: .5rem 1rem; max-inline-size: 32ch; text-wrap: balance; }
    &.syn-body { font: 400 var(--syn-type-body)/var(--syn-leading-body) var(--syn-font-ui); }
    &.syn-text-support { font: 400 var(--syn-type-sm)/1.5 var(--syn-font-ui); color: var(--syn-text-subtle); }
    /* Opt-in vertical rhythm; does not alter unwrapped host document styles. */
    &.syn-prose { max-width: 65ch; font: 400 var(--syn-type-body)/var(--syn-leading-body) var(--syn-font-ui); }
    &.syn-prose > :where(* + *) { margin-block-start: var(--syn-space-2); }
    &.syn-prose > :where(h2, h3, h4) { margin-block-start: var(--syn-space-4); }
    /* Explicit native content lists for core-only consumers. Native list markers,
       numbering, reversed/start/value semantics and wrapping remain intact. */
    &.syn-list {
      margin-block: var(--syn-space-2);
      padding-inline-start: 1.5rem;
      max-inline-size: 100%;
      line-height: var(--syn-leading-body);
    }
    &.syn-list > li {
      margin-block: var(--syn-list-item-gap, .35rem);
