        border-color: CanvasText;
      }
      &.syn-step[aria-current="step"]::before {
        border-color: Highlight;
        outline-color: Highlight;
      }
      &.syn-step[data-syn-state="error"]::before { border-style: dashed; }

      &.syn-stat, &.syn-empty, &.syn-price-card, &.syn-price-card[data-syn-featured] { border-color: CanvasText; }
      &.syn-avatar, &.syn-chip, &.syn-list-group, &.syn-divider-label::before, &.syn-divider-label::after { border-color: CanvasText; }
      &.syn-choice-card { border-color: CanvasText; }
      &.syn-choice-card:has(> .syn-input:checked),
      &.syn-filter-choices > .syn-chip:has(> input:checked) {
        border-color: Highlight; outline-color: Highlight;
      }
      &.syn-choice-card:has(> .syn-input:focus-visible),
      &.syn-filter-choices > .syn-chip:has(> input:focus-visible) {
        outline-color: Highlight;
      }
      &.syn-nav-tabs [aria-current="page"], &.syn-list-row[aria-current="page"] { border-color: Highlight; }
    }
  }
}
